    /*
     * Add to the Reports
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	ImagingOrder
     */
    public ImagingOrder addToReports( UUID parentId, ImagingReport addTo ) {
	    LOGGER.info("handling AssignReportsToImagingOrderEvent - " );
	    
	    ImagingOrder parentEntity = repository.findById(parentId).get();
	    ImagingReport child = registry.project( ImagingReport.class, addTo.getImagingReportId());
	    
	    parentEntity.getReports().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Reports
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	ImagingOrder
     */
	public ImagingOrder removeFromReports( UUID parentId, ImagingReport removeFrom ) {
	    LOGGER.info("handling RemoveReportsFromImagingOrderEvent " );
	
	    ImagingOrder parentEntity = repository.findById(parentId).get();
	    ImagingReport child = registry.project( ImagingReport.class, removeFrom.getImagingReportId());
	    
	    parentEntity.getReports().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



